/**
 * TTS Player for natural_20.py
 *
 * Handles playback of NPC speech audio generated by TTS providers.
 * Queues multiple audio clips and plays them sequentially.
 *
 * Integration:
 *   - Listens for conversation payloads / explicit playUrl() calls
 *   - Plays audio via HTML5 Audio API
 *   - Shows NPC name and emotion metadata
 *   - Falls back gracefully if audio is unavailable
 */

window.TTSPlayer = (function () {
    'use strict';

    var _audioQueue = [];
    var _isPlaying = false;
    var _currentAudio = null;
    var _currentAudioGain = 1.0;
    var _volume = 1.0;
    var _enabled = true;
    var _initialized = false;
    var _audioCtx = null;
    var _streams = {};
    var _deferredStreamBuffers = {};
    var _userGestureUnlocked = false;
    var _playedReplyIds = new Set();
    var _streamDeliveredReplyIds = new Set();
    var _streamAnnouncedReplyIds = new Set();
    var _pendingAutoplayReplyIds = new Set();
    var _pendingStreamStarts = [];
    var _playbackIdleWaiters = [];

    function unlockAudioForPlayback() {
        _userGestureUnlocked = true;
        var ctx = ensureAudioContext();
        if (ctx && ctx.state === 'suspended') {
            return ctx.resume().catch(function () {
                return null;
            });
        }
        return Promise.resolve(ctx);
    }

    function shouldAutoPlayAfterReady() {
        if (shouldAutoplay()) {
            return true;
        }
        if (!_userGestureUnlocked) {
            return false;
        }
        var mode = getDeliveryMode();
        return mode === 'async' || mode === 'stream';
    }

    var _deliveryMode = 'async';

    function normalizeDeliveryMode(mode) {
        var value = String(mode || '').trim().toLowerCase();
        if (value === 'streaming') {
            return 'stream';
        }
        if (value === 'click' || value === 'on_demand' || value === 'on-demand') {
            return 'manual';
        }
        if (value === 'async' || value === 'stream' || value === 'manual' || value === 'sync') {
            return value;
        }
        return '';
    }

    function configureDeliveryMode(mode) {
        var resolved = normalizeDeliveryMode(mode);
        if (resolved) {
            _deliveryMode = resolved;
        }
    }

    function getDeliveryMode() {
        return _deliveryMode;
    }

    function setDeliveryMode(mode) {
        configureDeliveryMode(mode);
    }

    function ensureAudioContext() {
        if (!_audioCtx) {
            var Ctx = window.AudioContext || window.webkitAudioContext;
            if (Ctx) {
                _audioCtx = new Ctx();
            }
        }
        if (_audioCtx && _audioCtx.state === 'suspended') {
            try {
                _audioCtx.resume();
            } catch (e) {}
        }
        return _audioCtx;
    }

    function shouldStreamAutoplay() {
        return getDeliveryMode() === 'stream' || shouldAutoplay();
    }

    function decodePcm16Mono(pcmB64) {
        var binary = atob(pcmB64 || '');
        var len = binary.length;
        var bytes = new Uint8Array(len);
        for (var i = 0; i < len; i++) {
            bytes[i] = binary.charCodeAt(i);
        }
        var samples = new Float32Array(len / 2);
        var view = new DataView(bytes.buffer);
        for (var j = 0; j < samples.length; j++) {
            samples[j] = view.getInt16(j * 2, true) / 32768;
        }
        return samples;
    }

    function getDeferredStreamBuffer(replyId) {
        if (!replyId) {
            return null;
        }
        if (!_deferredStreamBuffers[replyId]) {
            _deferredStreamBuffers[replyId] = { chunks: [], end: null };
        }
        return _deferredStreamBuffers[replyId];
    }

    function bufferStreamChunk(data) {
        var replyId = data.reply_id || data.replyId;
        if (!replyId || !data.pcm_b64) {
            return;
        }
        getDeferredStreamBuffer(replyId).chunks.push(data);
    }

    function bufferStreamEnd(data) {
        var replyId = data.reply_id || data.replyId;
        if (!replyId) {
            return;
        }
        getDeferredStreamBuffer(replyId).end = data;
    }

    function hasBufferedStreamChunks(replyId) {
        if (!replyId) {
            return false;
        }
        var buffer = _deferredStreamBuffers[replyId];
        return !!(buffer && buffer.chunks && buffer.chunks.length);
    }

    function pendingStreamStartFor(replyId) {
        if (!replyId) {
            return false;
        }
        var token = String(replyId);
        return _pendingStreamStarts.some(function (item) {
            var candidate = item && (item.reply_id || item.replyId);
            return candidate && String(candidate) === token;
        });
    }

    function shouldSuppressStreamWavAutoplay(replyKey) {
        if (!replyKey || getDeliveryMode() !== 'stream') {
            return false;
        }
        if (hasReplyPlayed(replyKey) || streamDeliveredAudio(replyKey)) {
            return true;
        }
        if (pendingStreamStartFor(replyKey)) {
            return true;
        }
        if (_streams[replyKey] || hasBufferedStreamChunks(replyKey)) {
            return true;
        }
        return false;
    }

    function flushDeferredStreamBuffer(replyId) {
        var buffer = _deferredStreamBuffers[replyId];
        if (!buffer) {
            return;
        }
        delete _deferredStreamBuffers[replyId];
        buffer.chunks.forEach(function (chunk) {
            onStreamChunk(chunk);
        });
        if (buffer.end) {
            onStreamEnd(buffer.end);
        }
    }

    function teardownStream(replyId, stream) {
        if (!stream) {
            return;
        }
        try {
            if (stream.gainNode) {
                stream.gainNode.disconnect();
            }
        } catch (e) {}
        if (replyId && _streams[replyId] === stream) {
            delete _streams[replyId];
        }
        if (replyId) {
            delete _deferredStreamBuffers[replyId];
        }
    }

    function isStreamPlaybackActive(excludeReplyId) {
        return Object.keys(_streams).some(function (replyId) {
            if (excludeReplyId && replyId === excludeReplyId) {
                return false;
            }
            var stream = _streams[replyId];
            if (!stream) {
                return false;
            }
            if (!stream.ended) {
                return true;
            }
            if (!_audioCtx) {
                return false;
            }
            return stream.playbackEndTime > _audioCtx.currentTime + 0.05;
        });
    }

    function isPlaybackActive() {
        return !!_isPlaying || isStreamPlaybackActive();
    }

    function notifyPlaybackIdleWaiters() {
        if (isPlaybackActive() || !_playbackIdleWaiters.length) {
            return;
        }
        var waiters = _playbackIdleWaiters.slice();
        _playbackIdleWaiters = [];
        waiters.forEach(function (callback) {
            try {
                callback();
            } catch (e) {
                console.warn('[TTSPlayer] playback idle callback failed:', e);
            }
        });
    }

    function schedulePlaybackIdleCheck() {
        if (!_audioCtx) {
            setTimeout(notifyPlaybackIdleWaiters, 0);
            return;
        }
        var latestEnd = _audioCtx.currentTime;
        Object.keys(_streams).forEach(function (replyId) {
            var stream = _streams[replyId];
            if (stream && !stream.ended && stream.playbackEndTime > latestEnd) {
                latestEnd = stream.playbackEndTime;
            }
        });
        var delayMs = Math.max(50, (latestEnd - _audioCtx.currentTime) * 1000 + 80);
        setTimeout(notifyPlaybackIdleWaiters, delayMs);
    }

    /**
     * Invoke callback once no HTML5 or stream-backed reply audio is playing.
     */
    function whenPlaybackIdle(callback) {
        if (typeof callback !== 'function') {
            return;
        }
        if (!isPlaybackActive()) {
            callback();
            return;
        }
        _playbackIdleWaiters.push(callback);
        schedulePlaybackIdleCheck();
    }

    function flushPendingStreamStarts() {
        while (_pendingStreamStarts.length && !isPlaybackActive()) {
            var next = _pendingStreamStarts.shift();
            if (next) {
                beginStreamStart(next);
            }
        }
    }

    function beginStreamStart(data) {
        data = data || {};
        if (!_enabled || !shouldStreamAutoplay()) {
            return;
        }
        unlockAudioForPlayback();
        var replyId = data.reply_id || data.replyId;
        var replyKey = replyId ? String(replyId) : '';
        if (!replyId) {
            return;
        }
        if (replyKey && hasReplyPlayed(replyKey) && !hasBufferedStreamChunks(replyKey)) {
            return;
        }
        if (_streams[replyId]) {
            teardownStream(replyId, _streams[replyId]);
        }
        var ctx = ensureAudioContext();
        if (!ctx) {
            return;
        }
        var gainVal = data.tts_gain;
        if (gainVal === undefined || gainVal === null) {
            gainVal = 1.0;
        } else {
            gainVal = parseFloat(gainVal);
            if (isNaN(gainVal)) {
                gainVal = 1.0;
            }
        }
        var gainNode = ctx.createGain();
        gainNode.gain.value = _volume * Math.max(0, Math.min(1, gainVal));
        gainNode.connect(ctx.destination);
        var leadIn = 0.12;
        _streams[replyId] = {
            ctx: ctx,
            gainNode: gainNode,
            nextTime: ctx.currentTime + leadIn,
            sampleRate: data.sample_rate || 24000,
            chunksReceived: 0,
            playbackEndTime: ctx.currentTime + leadIn,
            ended: false,
            sources: [],
        };
        showNPCSpeakingIndicator(normalizeSpeechData(data));
        flushDeferredStreamBuffer(replyId);
    }

    function onStreamStart(data) {
        data = data || {};
        var replyId = data.reply_id || data.replyId;
        if (replyId) {
            _streamAnnouncedReplyIds.add(String(replyId));
        }
        try {
            if (window.Chat && typeof window.Chat.applyTtsStreaming === 'function') {
                window.Chat.applyTtsStreaming(data);
            }
        } catch (e) {
            console.warn('[TTSPlayer] applyTtsStreaming failed:', e);
        }
        if (!_enabled || !shouldStreamAutoplay()) {
            return;
        }
        if (isPlaybackActive()) {
            _pendingStreamStarts.push(data);
            return;
        }
        beginStreamStart(data);
    }

    function onStreamChunk(data) {
        data = data || {};
        var replyId = data.reply_id || data.replyId;
        var stream = replyId ? _streams[replyId] : null;
        if (!stream || stream.ended || !data.pcm_b64) {
            if (replyId && data.pcm_b64) {
                bufferStreamChunk(data);
            }
            return;
        }
        unlockAudioForPlayback();
        var samples = decodePcm16Mono(data.pcm_b64);
        if (!samples.length) {
            return;
        }
        var sampleRate = data.sample_rate || stream.sampleRate || 24000;
        stream.sampleRate = sampleRate;
        var buffer = stream.ctx.createBuffer(1, samples.length, sampleRate);
        buffer.getChannelData(0).set(samples);
        var source = stream.ctx.createBufferSource();
        source.buffer = buffer;
        source.connect(stream.gainNode);
        var now = stream.ctx.currentTime;
        // If we fell behind (tab backgrounded / bursty socket), resync instead of skipping samples.
        if (stream.nextTime < now - 0.02) {
            stream.nextTime = now + 0.03;
        }
        var startAt = stream.nextTime;
        source.start(startAt);
        stream.nextTime = startAt + buffer.duration;
        stream.playbackEndTime = stream.nextTime;
        stream.chunksReceived += 1;
        stream.sources.push(source);
        if (_playbackIdleWaiters.length) {
            schedulePlaybackIdleCheck();
        }
    }

    function markReplyPlayed(replyId) {
        if (replyId) {
            _playedReplyIds.add(String(replyId));
        }
    }

    function hasReplyPlayed(replyId) {
        return !!(replyId && _playedReplyIds.has(String(replyId)));
    }

    function applyTtsReadyUi(data) {
        try {
            if (typeof window.Chat !== 'undefined' && window.Chat && typeof window.Chat.applyTtsReady === 'function') {
                window.Chat.applyTtsReady(data);
            }
        } catch (e) {
            console.warn('[TTSPlayer] applyTtsReady failed:', e);
        }
    }

    function tryPlayTtsOnce(data) {
        return playReplyAudio(data);
    }

    function streamDeliveredAudio(replyId) {
        if (!replyId) {
            return false;
        }
        if (_streamDeliveredReplyIds.has(String(replyId))) {
            return true;
        }
        var stream = _streams[replyId];
        return !!(stream && stream.chunksReceived > 0);
    }

    /**
     * Autoplay a finalized reply exactly once (socket + poll may both fire).
     */
    function playReplyAudio(data, options) {
        data = data || {};
        options = options || {};
        var replyId = data.reply_id || data.replyId;
        var replyKey = replyId ? String(replyId) : '';
        var audioUrl = data.audio_url || data.audioUrl;
        if (!audioUrl) {
            return false;
        }
        applyTtsReadyUi(data);
        if (!options.streamWavFallback && shouldSuppressStreamWavAutoplay(replyKey)) {
            markReplyPlayed(replyKey);
            return false;
        }
        if (replyKey) {
            if (hasReplyPlayed(replyKey) || streamDeliveredAudio(replyKey)) {
                markReplyPlayed(replyKey);
                return false;
            }
            if (_pendingAutoplayReplyIds.has(replyKey)) {
                return false;
            }
        }
        if (!shouldAutoPlayAfterReady()) {
            return false;
        }
        if (isPlaybackActive()) {
            if (replyKey) {
                _pendingAutoplayReplyIds.add(replyKey);
            }
            whenPlaybackIdle(function () {
                if (replyKey) {
                    _pendingAutoplayReplyIds.delete(replyKey);
                }
                playReplyAudio(data);
            });
            return false;
        }
        if (replyId && _streams[replyId]) {
            var activeStream = _streams[replyId];
            if (activeStream.chunksReceived > 0 || !activeStream.ended) {
                markReplyPlayed(replyId);
                return false;
            }
            teardownStream(replyId, activeStream);
        }
        markReplyPlayed(replyId);
        onNPCSpeech(Object.assign({}, data, {
            audio_url: audioUrl,
            audioUrl: audioUrl,
        }));
        return true;
    }

    function onStreamEnd(data) {
        data = data || {};
        var replyId = data.reply_id || data.replyId;
        var stream = replyId ? _streams[replyId] : null;
        var audioUrl = data.audio_url || data.audioUrl;
        var chunksPlayed = stream ? stream.chunksReceived : 0;

        if (!stream) {
            bufferStreamEnd(data);
            applyTtsReadyUi(data);
            return;
        }

        stream.ended = true;
        if (chunksPlayed > 0 && replyId) {
            _streamDeliveredReplyIds.add(String(replyId));
            markReplyPlayed(replyId);
        }
        var cleanupDelay = Math.max(
            300,
            (stream.playbackEndTime - stream.ctx.currentTime) * 1000 + 200
        );
        setTimeout(function () {
            teardownStream(replyId, stream);
            notifyPlaybackIdleWaiters();
            flushPendingStreamStarts();
        }, cleanupDelay);

        // Live stream failed entirely — one-shot WAV fallback (never stack on PCM).
        if (audioUrl && chunksPlayed === 0) {
            unlockAudioForPlayback();
            playReplyAudio(data, { streamWavFallback: true });
        }

        if (replyId && !audioUrl) {
            try {
                if (typeof window.Chat !== 'undefined' && window.Chat && typeof window.Chat.clearTtsPendingUi === 'function') {
                    window.Chat.clearTtsPendingUi(replyId);
                }
                if (typeof window.Chat !== 'undefined' && window.Chat && typeof window.Chat.scheduleTtsReplyPoll === 'function') {
                    window.Chat.scheduleTtsReplyPoll(replyId);
                }
            } catch (e) {
                console.warn('[TTSPlayer] clear pending UI failed:', e);
            }
        }
        applyTtsReadyUi(data);
    }

    function initCampaignDeliveryMode() {
        if (typeof window.N20_TTS_DELIVERY !== 'undefined' && window.N20_TTS_DELIVERY) {
            configureDeliveryMode(window.N20_TTS_DELIVERY);
            return;
        }
        if (typeof $ !== 'undefined' && $.getJSON) {
            $.getJSON('/tts/preferences', function (resp) {
                if (resp && resp.delivery_mode) {
                    configureDeliveryMode(resp.delivery_mode);
                }
            });
        }
    }

    /**
     * Initialize the TTS player.
     * Call this once when the page loads.
     */
    function init(socket) {
        if (_initialized) {
            return;
        }
        _initialized = true;

        // Bind only the shared Socket.IO connection (never open a second client).
        try {
            var soc = socket || window.socket || window.socketio || null;
            if (soc && typeof soc.on === 'function') {
                soc.on('npc_speech', function (data) {
                    onNPCSpeech(data);
                });
                soc.on('tts_ready', function (data) {
                    onTtsReady(data);
                });
                soc.on('tts_stream_start', function (data) {
                    onStreamStart(data);
                });
                soc.on('tts_stream_chunk', function (data) {
                    onStreamChunk(data);
                });
                soc.on('tts_stream_end', function (data) {
                    onStreamEnd(data);
                });
            }
        } catch (e) {
            console.warn('[TTSPlayer] Socket bind failed:', e);
        }

        initCampaignDeliveryMode();

        // Check for saved volume preference
        try {
            var savedVol = localStorage.getItem('n20.tts.volume');
            if (savedVol !== null) {
                _volume = parseFloat(savedVol) || 1.0;
            }
            var savedEnabled = localStorage.getItem('n20.tts.enabled');
            if (savedEnabled !== null) {
                _enabled = savedEnabled !== 'false';
            }
        } catch (e) {
            // localStorage may not be available
        }

        console.log('[TTSPlayer] Initialized (enabled:', _enabled, ', volume:', _volume, ')');
    }

    /**
     * Normalize incoming speech payloads (snake_case or camelCase).
     */
    function normalizeSpeechData(data) {
        data = data || {};
        var gain = data.ttsGain;
        if (gain === undefined || gain === null) {
            gain = data.tts_gain;
        }
        if (gain === undefined || gain === null) {
            gain = 1.0;
        } else {
            gain = parseFloat(gain);
            if (isNaN(gain)) {
                gain = 1.0;
            }
        }
        return {
            audioUrl: data.audioUrl || data.audio_url || '',
            npcName: data.npcName || data.npc_name || 'NPC',
            npcUid: data.npcUid || data.npc_uid || '',
            emotion: data.emotion || data.tts_emotion || 'calm',
            timestamp: data.timestamp || Date.now() / 1000,
            ttsGain: Math.max(0, Math.min(1, gain)),
        };
    }

    /**
     * Handle async TTS completion — upgrade pending speak buttons.
     */
    function onTtsReady(data) {
        data = data || {};
        // Stream mode: live PCM handles autoplay; tts_ready WAV is replay-only unless PCM never arrived.
        if (getDeliveryMode() === 'stream') {
            applyTtsReadyUi(data);
            var replyId = data.reply_id || data.replyId;
            var replyKey = replyId ? String(replyId) : '';
            if (shouldSuppressStreamWavAutoplay(replyKey)) {
                markReplyPlayed(replyId);
                return;
            }
            playReplyAudio(data, { streamWavFallback: true });
            return;
        }
        playReplyAudio(data);
    }

    function shouldAutoplay() {
        try {
            return localStorage.getItem('n20.tts.autoplay') === 'true';
        } catch (e) {
            return false;
        }
    }

    function setAutoplay(enabled) {
        try {
            localStorage.setItem('n20.tts.autoplay', enabled ? 'true' : 'false');
        } catch (e) {}
    }

    function isAutoplayEnabled() {
        return shouldAutoplay();
    }

    /**
     * Handle incoming NPC speech event.
     */
    function onNPCSpeech(data) {
        if (!_enabled) {
            console.log('[TTSPlayer] Skipping (disabled):', data && (data.npc_name || data.npcName));
            return;
        }

        unlockAudioForPlayback();
        var normalized = normalizeSpeechData(data);
        if (!normalized.audioUrl) {
            console.warn('[TTSPlayer] Missing audio URL in speech payload', data);
            return;
        }
        queueAudio(normalized);
    }

    /**
     * Play a specific audio URL immediately (used by replay buttons).
     * Clears the current queue so replay is responsive.
     */
    function playUrl(audioUrl, meta) {
        if (!audioUrl) {
            return false;
        }
        if (!_enabled) {
            setEnabled(true);
        }
        unlockAudioForPlayback();
        stop();
        queueAudio(normalizeSpeechData(Object.assign({}, meta || {}, {
            audio_url: audioUrl,
            audioUrl: audioUrl,
        })));
        return true;
    }

    /**
     * Queue an audio clip for playback.
     */
    function normalizeAudioUrl(url) {
        try {
            return new URL(url, window.location.origin).pathname;
        } catch (e) {
            return String(url || '');
        }
    }

    function queueAudio(audioData) {
        if (!audioData || !audioData.audioUrl) {
            return;
        }
        if (isPlaybackActive()) {
            whenPlaybackIdle(function () {
                queueAudio(audioData);
            });
            return;
        }
        var urlKey = normalizeAudioUrl(audioData.audioUrl);
        if (_currentAudio && _currentAudio.src && normalizeAudioUrl(_currentAudio.src) === urlKey) {
            return;
        }
        for (var i = 0; i < _audioQueue.length; i++) {
            if (normalizeAudioUrl(_audioQueue[i].audioUrl) === urlKey) {
                return;
            }
        }
        _audioQueue.push(audioData);
        playNext();
    }

    /**
     * Play the next audio clip in the queue.
     */
    function playNext() {
        if (_isPlaying || _audioQueue.length === 0 || !_enabled) {
            return;
        }
        if (isStreamPlaybackActive()) {
            whenPlaybackIdle(playNext);
            return;
        }

        _isPlaying = true;
        var audioData = _audioQueue[0];

        // Create audio element — src must be set before play()
        var audio = new Audio(audioData.audioUrl);
        audio.preload = 'auto';
        var gain = audioData.ttsGain !== undefined && audioData.ttsGain !== null ? audioData.ttsGain : 1.0;
        audio.volume = _volume * gain;
        _currentAudio = audio;
        _currentAudioGain = gain;

        // Handle audio ended
        audio.addEventListener('ended', function () {
            _isPlaying = false;
            _currentAudio = null;
            _audioQueue.shift();
            playNext();
            notifyPlaybackIdleWaiters();
            flushPendingStreamStarts();
        });

        // Handle audio error
        audio.addEventListener('error', function (e) {
            console.warn('[TTSPlayer] Audio playback failed:', e, 'URL:', audioData.audioUrl);
            _isPlaying = false;
            _currentAudio = null;
            _audioQueue.shift();
            showAudioUnavailableNotification(audioData.npcName);
            playNext();
            notifyPlaybackIdleWaiters();
            flushPendingStreamStarts();
        });

        // Show NPC info while playing
        showNPCSpeakingIndicator(audioData);

        // Try to play
        var playPromise = audio.play();
        if (playPromise && typeof playPromise.catch === 'function') {
            playPromise.catch(function (err) {
                console.warn('[TTSPlayer] Play failed:', err);
                _isPlaying = false;
                _currentAudio = null;
                _audioQueue.shift();
                playNext();
            });
        }
    }

    /**
     * Show a visual indicator that an NPC is speaking.
     */
    function showNPCSpeakingIndicator(audioData) {
        var indicator = document.getElementById('n20-tts-speaking-indicator');
        if (!indicator) {
            indicator = document.createElement('div');
            indicator.id = 'n20-tts-speaking-indicator';
            indicator.className = 'n20-tts-speaking-indicator';
            indicator.innerHTML = '<span class="n20-tts-npc-name"></span> <span class="n20-tts-emotion"></span>';
            indicator.style.cssText = 'position:fixed;bottom:20px;right:20px;background:rgba(0,0,0,0.8);color:#fff;padding:8px 16px;border-radius:20px;font-size:14px;z-index:10000;transition:opacity 0.3s;display:none;';
            document.body.appendChild(indicator);
        }

        var nameEl = indicator.querySelector('.n20-tts-npc-name');
        var emotionEl = indicator.querySelector('.n20-tts-emotion');
        if (nameEl) nameEl.textContent = audioData.npcName || 'NPC';
        if (emotionEl) emotionEl.textContent = audioData.emotion ? '(' + audioData.emotion + ')' : '';

        indicator.style.display = 'block';
        indicator.style.opacity = '1';

        setTimeout(function () {
            indicator.style.opacity = '0';
            setTimeout(function () {
                if (indicator.style.opacity === '0') {
                    indicator.style.display = 'none';
                }
            }, 300);
        }, 5000);
    }

    /**
     * Show notification when audio is unavailable.
     */
    function showAudioUnavailableNotification(npcName) {
        console.log('[TTSPlayer] Audio unavailable for:', npcName);
    }

    /**
     * Stop current playback and clear the queue.
     */
    function stop() {
        if (_currentAudio) {
            try {
                _currentAudio.pause();
            } catch (e) {}
            _currentAudio = null;
        }
        _isPlaying = false;
        _audioQueue = [];
    }

    /**
     * Set the TTS volume (0.0 to 1.0).
     */
    function setVolume(vol) {
        _volume = Math.max(0, Math.min(1, vol));
        try {
            localStorage.setItem('n20.tts.volume', _volume.toString());
        } catch (e) {}

        if (_currentAudio) {
            _currentAudio.volume = _volume * (_currentAudioGain || 1.0);
        }
        Object.keys(_streams).forEach(function (replyId) {
            var stream = _streams[replyId];
            if (stream && stream.gainNode) {
                stream.gainNode.gain.value = _volume;
            }
        });
    }

    function getVolume() {
        return _volume;
    }

    function setEnabled(enabled) {
        _enabled = !!enabled;
        try {
            localStorage.setItem('n20.tts.enabled', _enabled.toString());
        } catch (e) {}

        if (!_enabled) {
            stop();
            _streams = {};
        }
    }

    function isEnabled() {
        return _enabled;
    }

    function getQueueLength() {
        return _audioQueue.length;
    }

    function getCurrentAudio() {
        if (_audioQueue.length > 0) {
            return _audioQueue[0];
        }
        return null;
    }

    // Public API
    return {
        init: init,
        onNPCSpeech: onNPCSpeech,
        playUrl: playUrl,
        queueAudio: queueAudio,
        stop: stop,
        setVolume: setVolume,
        getVolume: getVolume,
        setEnabled: setEnabled,
        isEnabled: isEnabled,
        getQueueLength: getQueueLength,
        getCurrentAudio: getCurrentAudio,
        shouldAutoplay: shouldAutoplay,
        setAutoplay: setAutoplay,
        isAutoplayEnabled: isAutoplayEnabled,
        onTtsReady: onTtsReady,
        playReplyAudio: playReplyAudio,
        onStreamStart: onStreamStart,
        onStreamChunk: onStreamChunk,
        onStreamEnd: onStreamEnd,
        getDeliveryMode: getDeliveryMode,
        setDeliveryMode: setDeliveryMode,
        initCampaignDeliveryMode: initCampaignDeliveryMode,
        unlockAudioForPlayback: unlockAudioForPlayback,
        markReplyPlayed: markReplyPlayed,
        hasReplyPlayed: hasReplyPlayed,
        isPlaybackActive: isPlaybackActive,
        whenPlaybackIdle: whenPlaybackIdle,
    };
})();
